main.script:
(function () {
  'use strict';
  var EASE = 'cubic-bezier(.16,1,.3,1)';
  var REDUCED = false, HAS_IO = 'IntersectionObserver' in window, HAS_RO = 'ResizeObserver' in window;
  var ORDER = [];                                   /* ids in the order the directory currently shows them */
  function $(s, c) { return (c || document).querySelector(s); }
  function $all(s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); }
  function kids(el) { return Array.prototype.slice.call(el.children); }
  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
  function smooth() { return REDUCED ? 'auto' : 'smooth'; }
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function idOf(href) { var m = /[?&]id=([^&#]+)/.exec(href || ''); return m ? decodeURIComponent(m[1]) : ''; }
  function belowFold(el) { return el.getBoundingClientRect().top > (window.innerHeight || 800) - 8; }
  function onceVisible(el, cb, opts) {
    if (!HAS_IO) { cb(); return; }
    var io = new IntersectionObserver(function (es) { es.forEach(function (en) { if (en.isIntersecting) { io.disconnect(); cb(en); } }); }, opts || {});
    io.observe(el);
  }
  function people() { return window.TRE_FACILITATORS || []; }
  function ordered() {
    var all = people(), by = {}; all.forEach(function (f) { by[f.id] = f; });
    var list = ORDER.map(function (id) { return by[id]; }).filter(Boolean);
    return list.length === all.length ? list : all.slice();
  }
  /* main.js turns every TRE™ into a tappable explainer once, on load; cards it re-renders on filtering get the same treatment here */
  var TERM_SKIP = 'script,style,textarea,input,select,option,a,button,.btn,summary,.tre-term,.tre-pop,svg,figcaption,.lx-strip';
  function termify(root) {
    if (!root || !document.createTreeWalker) return;
    var w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode: function (t) {
      if (!/TRE[®™]/.test(t.nodeValue)) return NodeFilter.FILTER_REJECT;
      var p = t.parentElement; return !p || p.closest(TERM_SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; } });
    var list = []; while (w.nextNode()) list.push(w.currentNode);
    list.forEach(function (t) {
      var frag = document.createDocumentFragment();
      t.nodeValue.split(/(TRE[®™])/).forEach(function (part) {
        if (/^TRE[®™]$/.test(part)) { var a = document.createElement('abbr'); a.className = 'tre-term'; a.setAttribute('role', 'button'); a.setAttribute('tabindex', '0'); a.setAttribute('title', 'What does TRE™ stand for?'); a.textContent = 'TRE™'; frag.appendChild(a); }
        else if (part) frag.appendChild(document.createTextNode(part));
      });
      t.parentNode.replaceChild(frag, t);
    });
  }
  function faces(list, cls) {
    return list.filter(function (f) { return f && f.photo; }).map(function (f) {
      var href = window.TRE_recUrl ? window.TRE_recUrl('providers', f.id) : 'provider?id=' + encodeURIComponent(f.id);
      var img = window.TRE_pic ? window.TRE_pic(f.photo, '', '64px', ' width="64" height="64" loading="lazy" decoding="async"') : '<img src="' + esc(f.photo) + '" alt="" width="64" height="64" loading="lazy" decoding="async">';
      return '<a class="' + cls + '" href="' + esc(href) + '" aria-label="View profile: ' + esc(f.name) + '" data-name="' + esc(f.name) + '">' + img + '</a>';
    }).join('');
  }

  /* ---------- 1 · Directory: sticky toolbar, live counts, FLIP re-layout ---------- */
  function directory() {
    var dir = $('.fc-dir'); if (!dir) return;
    var browse = $('.fc-browse', dir), tools = $('.fc-tools', dir), segWrap = $('.fc-seg-wrap', dir);
    var seg = $('[data-fac-filter="kind"]', dir), chips = $('[data-fac-filter="mode"]', dir), search = $('[data-fac-search]', dir);
    var countEl = $('[data-fac-count]', dir), stage = $('.fc-stage', dir), grid = $('[data-providers-grid]', dir), header = $('.site-header');
    if (!browse || !seg || !chips || !grid || !stage) return;
    var DATA = people();

    function head() { if (header) browse.style.setProperty('--fc-head', Math.round(header.getBoundingClientRect().height) + 'px'); }
    head(); if (HAS_RO && header) new ResizeObserver(head).observe(header);

    /* hover-capable pointers get the contact tray; touch keeps the actions in the card */
    var fineMQ = window.matchMedia ? window.matchMedia('(hover: hover) and (pointer: fine) and (min-width: 761px)') : null;
    function setFine() { dir.classList.toggle('fc-fine', !!(fineMQ && fineMQ.matches)); }
    setFine();
    if (fineMQ) { if (fineMQ.addEventListener) fineMQ.addEventListener('change', setFine); else if (fineMQ.addListener) fineMQ.addListener(setFine); }

    /* sliding thumb under the active role */
    var thumb = document.createElement('span'); thumb.className = 'fc-seg-thumb is-instant'; thumb.setAttribute('aria-hidden', 'true');
    seg.insertBefore(thumb, seg.firstChild); seg.classList.add('has-thumb');
    function thumbTo(instant) {
      var a = $('.filter-btn.active', seg); if (!a) { thumb.style.opacity = '0'; return; }
      if (instant) thumb.classList.add('is-instant');
      thumb.style.opacity = '1'; thumb.style.top = a.offsetTop + 'px'; thumb.style.height = a.offsetHeight + 'px'; thumb.style.width = a.offsetWidth + 'px';
      thumb.style.transform = 'translateX(' + a.offsetLeft + 'px)';
      if (instant) { void thumb.offsetWidth; requestAnimationFrame(function () { thumb.classList.remove('is-instant'); }); }
    }
    function edges(row) {
      var max = row.scrollWidth - row.clientWidth, over = max > 6, x = row.scrollLeft;
      row.classList.toggle('fc-over', over); row.classList.toggle('fc-mid', over && x > 6 && x < max - 6); row.classList.toggle('fc-end', over && x >= max - 6);
    }
    function keep(row, el) {
      if (!el) return; var max = row.scrollWidth - row.clientWidth; if (max <= 1) return;
      var l = el.offsetLeft, r = l + el.offsetWidth;
      if (l < row.scrollLeft + 12) row.scrollTo({ left: Math.max(0, l - 28), behavior: smooth() });
      else if (r > row.scrollLeft + row.clientWidth - 12) row.scrollTo({ left: Math.min(max, r - row.clientWidth + 28), behavior: smooth() });
    }
    [seg, chips].forEach(function (row) { row.addEventListener('scroll', function () { edges(row); }, { passive: true }); });

    /* faceted counts: the same match rules main.js filters with */
    function hay(f) { return [f.name, f.role, f.bio, f.tag, (f.services || []).join(' '), (f.meta || []).map(function (m) { return m.text; }).join(' '), f.facts && f.facts.location, f.facts && f.facts.languages].join(' ').toLowerCase(); }
    var HAY = DATA.map(hay);
    function state() { var k = $('.filter-btn.active', seg), m = $('.chip.active', chips); return { kind: k ? k.getAttribute('data-value') : 'all', mode: m ? m.getAttribute('data-value') : 'all', q: search ? search.value.trim().toLowerCase() : '' }; }
    function n(kind, mode, q) { var c = 0; DATA.forEach(function (f, i) { if ((kind === 'all' || f.kind === kind) && (mode === 'all' || (f.modes || []).indexOf(mode) >= 0) && (!q || HAY[i].indexOf(q) >= 0)) c++; }); return c; }
    function mark(btn, c, withNum) {
      btn.classList.toggle('is-zero', c === 0); btn.setAttribute('aria-pressed', btn.classList.contains('active') ? 'true' : 'false');
      if (!withNum) return;
      var s = $('.fc-n', btn); if (!s) { s = document.createElement('span'); s.className = 'fc-n'; btn.appendChild(s); }
      s.textContent = ' ' + c;
    }
    function boldCount() {
      if (!countEl || countEl.querySelector('b')) return;
      var m = /^(\d+) of (\d+)([\s\S]*)$/.exec(countEl.textContent || ''); if (!m) return;
      var b1 = document.createElement('b'), b2 = document.createElement('b'); b1.textContent = m[1]; b2.textContent = m[2];
      countEl.textContent = ''; countEl.appendChild(b1); countEl.appendChild(document.createTextNode(' of ')); countEl.appendChild(b2); countEl.appendChild(document.createTextNode(m[3]));
    }
    function enhanceEmpty(box, s) {
      if (box.__fc) return; box.__fc = true;
      var row = document.createElement('div'); row.className = 'fc-empty-faces'; row.innerHTML = faces(ordered(), 'fc-face-sm');
      if (row.innerHTML) box.insertBefore(row, box.firstChild);
      if (s.kind === 'trainee') {
        var p = document.createElement('p'); p.className = 'fc-empty-note';
        p.innerHTML = 'Certified providers and providers-in-training can be listed here at no cost, with the same card, profile page and gallery as everyone else. <a class="link-arrow" href="#get-listed">Get listed</a>';
        box.appendChild(p);
      }
    }
    function decorate() {
      var s = state();
      $all('.filter-btn', seg).forEach(function (b) { mark(b, n(b.getAttribute('data-value'), s.mode, s.q), true); });
      $all('.chip', chips).forEach(function (b) { mark(b, n(s.kind, b.getAttribute('data-value'), s.q), false); });
      thumbTo(false); boldCount(); edges(seg); edges(chips); termify(grid);
      var ids = $all('.fac-card a.fac-photo', grid).map(function (a) { return idOf(a.getAttribute('href')); });
      if (ids.length && ids.length === DATA.length) ORDER = ids;
      var empty = $('.event-empty', grid); if (empty) enhanceEmpty(empty, s);
    }

    /* FLIP: record where every card is just before main.js re-renders (capture phase runs first) */
    var snap = null, act = '';
    function keyOf(el) { if (el.classList.contains('event-empty')) return '#empty'; var a = el.querySelector('a.fac-photo'); return a ? a.getAttribute('href') : ''; }
    function snapshot(kind) {
      act = kind; if (snap) return;
      var map = {}; kids(grid).forEach(function (el) { var k = keyOf(el); if (k) map[k] = { r: el.getBoundingClientRect(), el: el }; });
      snap = { map: map, h: stage.getBoundingClientRect().height };
    }
    browse.addEventListener('click', function (e) {
      var t = e.target && e.target.closest ? e.target.closest('[data-fac-filter] button, [data-fac-shuffle], [data-fac-reset]') : null;
      if (t) snapshot(t.hasAttribute('data-fac-reset') ? 'reset' : t.hasAttribute('data-fac-shuffle') ? 'shuffle' : 'filter');
    }, true);
    browse.addEventListener('input', function (e) { if (e.target === search) snapshot('search'); }, true);

    function play(s) {
      var sr = stage.getBoundingClientRect(), seen = {}, i = 0;
      kids(grid).forEach(function (el) {
        var k = keyOf(el), old = k && s.map[k], r = el.getBoundingClientRect();
        if (old) {
          seen[k] = 1; if (k === '#empty') return;
          var dx = old.r.left - r.left, dy = old.r.top - r.top;
          if (Math.abs(dx) > .5 || Math.abs(dy) > .5) el.animate([{ transform: 'translate(' + dx.toFixed(1) + 'px,' + dy.toFixed(1) + 'px)' }, { transform: 'translate(0,0)' }], { duration: 540, easing: EASE });
        } else {
          el.animate([{ opacity: 0, transform: 'translateY(14px) scale(.985)', filter: 'blur(6px)' }, { opacity: 1, transform: 'none', filter: 'blur(0px)' }], { duration: 560, delay: 110 + Math.min(i++, 6) * 60, easing: EASE, fill: 'backwards' });
        }
      });
      Object.keys(s.map).forEach(function (k) {                 /* leavers fade out where they stood */
        if (seen[k]) return;
        var v = s.map[k], g = v.el;
        if (g.getAnimations) g.getAnimations().forEach(function (a) { a.cancel(); });
        g.classList.add('fc-ghost'); g.setAttribute('aria-hidden', 'true'); g.setAttribute('inert', '');
        g.style.left = (v.r.left - sr.left) + 'px'; g.style.top = (v.r.top - sr.top) + 'px'; g.style.width = v.r.width + 'px'; g.style.height = v.r.height + 'px';
        stage.appendChild(g);
        var a = g.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'scale(.97)' }], { duration: 260, easing: 'cubic-bezier(.4,0,1,1)', fill: 'forwards' });
        a.onfinish = function () { g.remove(); };
      });
      if (stage.__ha) { stage.__ha.cancel(); stage.__ha = null; }  /* the page below glides instead of jumping */
      var h1 = stage.getBoundingClientRect().height;
      if (Math.abs(h1 - s.h) > 2) {
        stage.classList.add('fc-clip');
        var ha = stage.animate([{ height: s.h + 'px' }, { height: h1 + 'px' }], { duration: 540, easing: EASE }); stage.__ha = ha;
        ha.onfinish = ha.oncancel = function () { if (stage.__ha === ha || !stage.__ha) stage.classList.remove('fc-clip'); if (stage.__ha === ha) stage.__ha = null; };
      }
    }
    function afterRender() {
      keep(seg, $('.filter-btn.active', seg)); keep(chips, $('.chip.active', chips));
      if (act === 'reset') { var all = $('.filter-btn[data-value="all"]', seg); if (all) { try { all.focus({ preventScroll: true }); } catch (e) { all.focus(); } } }
      var wide = window.innerWidth > 1040, bar = wide ? tools : segWrap;
      if (!bar || !bar.classList.contains('is-stuck')) return;
      var target = wide ? stage : (countEl || stage), gap = wide ? 16 : 12;
      var top = target.getBoundingClientRect().top, bottom = bar.getBoundingClientRect().bottom;
      if (top < bottom + gap - 1) window.scrollBy({ top: top - bottom - gap, behavior: smooth() });
    }
    new MutationObserver(function () {
      var s = snap; snap = null;
      decorate();
      if (s && !REDUCED && typeof grid.animate === 'function') play(s);
      if (s) afterRender();
    }).observe(grid, { childList: true });

    /* stuck state (shadow) */
    var ticking = false;
    function stuck() {
      ticking = false;
      var wide = window.innerWidth > 1040, el = wide ? tools : segWrap, other = wide ? segWrap : tools;
      if (other) other.classList.remove('is-stuck'); if (!el) return;
      var r = el.getBoundingClientRect(), want = parseFloat(getComputedStyle(el).top) || 0, b = browse.getBoundingClientRect().bottom;
      el.classList.toggle('is-stuck', window.scrollY > 0 && r.top <= want + 1 && b > r.bottom + 24);
    }
    window.addEventListener('scroll', function () { if (!ticking) { ticking = true; requestAnimationFrame(stuck); } }, { passive: true });
    window.addEventListener('resize', function () { thumbTo(true); edges(seg); edges(chips); stuck(); });

    /* the first time the grid arrives, the cards settle in as a list */
    if (!REDUCED && HAS_IO && belowFold(stage)) {
      var first = $('.fac-card', grid);
      if (first) {
        $all('.fac-card', grid).forEach(function (c) { c.classList.add('fc-pre'); });
        onceVisible(first, function () {
          $all('.fac-card.fc-pre', grid).forEach(function (c, i) {
            c.classList.remove('fc-pre');
            if (c.animate) c.animate([{ opacity: 0, transform: 'translateY(18px)', filter: 'blur(6px)' }, { opacity: 1, transform: 'none', filter: 'blur(0px)' }], { duration: 760, delay: i * 90, easing: EASE, fill: 'backwards' });
          });
        }, { rootMargin: '0px 0px -8% 0px' });
      }
    }
    decorate(); thumbTo(true); stuck();
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(function () { thumbTo(true); edges(seg); edges(chips); });
    if (HAS_RO) new ResizeObserver(function () { thumbTo(true); edges(seg); edges(chips); }).observe(seg);
  }

  /* ---------- 2 · Community strip: photos develop out of navy as they come into view ---------- */
  function strip() {
    var el = $('.fc-strip'); if (!el) return;
    var shots = $all('.fc-shot', el);
    if (!REDUCED && HAS_IO) {
      var io = new IntersectionObserver(function (es) { es.forEach(function (en) { if (en.isIntersecting) { en.target.classList.remove('fc-undev'); io.unobserve(en.target); } }); }, { threshold: 0.45 });
      shots.forEach(function (s) { var r = s.getBoundingClientRect(); if (r.top > window.innerHeight - 8 || r.left > window.innerWidth - 8) { s.classList.add('fc-undev'); io.observe(s); } });
    }
    var ctl = $('.fc-gal-ctl'), bar = $('.fc-gal-bar i'), prev = $('[data-fc-gal="-1"]'), next = $('[data-fc-gal="1"]');
    function upd() {
      var sw = el.scrollWidth, cw = el.clientWidth, max = sw - cw;
      if (ctl) ctl.classList.toggle('is-idle', max <= 2);
      if (bar) { bar.style.width = (sw ? cw / sw * 100 : 100).toFixed(2) + '%'; bar.style.left = (sw ? el.scrollLeft / sw * 100 : 0).toFixed(2) + '%'; }
      if (prev) prev.disabled = el.scrollLeft <= 2;
      if (next) next.disabled = el.scrollLeft >= max - 2;
    }
    var t = false;
    el.addEventListener('scroll', function () { if (!t) { t = true; requestAnimationFrame(function () { t = false; upd(); }); } }, { passive: true });
    window.addEventListener('resize', upd); upd();
    function go(d) { el.scrollBy({ left: d * Math.max(260, el.clientWidth * 0.66), behavior: smooth() }); }
    if (prev) prev.addEventListener('click', function () { go(-1); });
    if (next) next.addEventListener('click', function () { go(1); });
  }

  /* ---------- 3 · The module path draws itself; the line trembles as it is drawn, then settles ---------- */
  function certPath() {
    var fig = $('[data-fc-path]'); if (!fig) return;
    var svg = $('.fc-path-svg', fig), ln = $('.fc-path-ln', fig), nodes = $all('.fc-path-steps > li', fig);
    if (!svg || !ln || nodes.length < 2) return;
    fig.classList.add('fc-js');
    var pts = [], segs = [], total = 1, phase = REDUCED ? 'done' : 'wait', t0 = 0, DUR = 1.6, TAU = 0.3, AMP = 4;
    function geom() {
      var fr = fig.getBoundingClientRect();
      svg.setAttribute('viewBox', '0 0 ' + Math.max(1, Math.round(fr.width)) + ' ' + Math.max(1, Math.round(fr.height)));
      pts = nodes.map(function (li) { var r = li.getBoundingClientRect(); return { x: r.left - fr.left + 8, y: r.top - fr.top + 8 }; });
      segs = []; total = 0;
      for (var i = 0; i < pts.length - 1; i++) { var dx = pts[i + 1].x - pts[i].x, dy = pts[i + 1].y - pts[i].y, l = Math.sqrt(dx * dx + dy * dy) || 1; segs.push({ x: pts[i].x, y: pts[i].y, ux: dx / l, uy: dy / l, l: l, s0: total }); total += l; }
      total = total || 1;
    }
    function point(s, t) {
      var g = segs[segs.length - 1];
      for (var i = 0; i < segs.length; i++) if (s <= segs[i].s0 + segs[i].l) { g = segs[i]; break; }
      var u = clamp(s - g.s0, 0, g.l), env = Math.sin(Math.PI * u / g.l);                   /* anchored at every node */
      var age = t - DUR * (1 - Math.cbrt(1 - clamp(s / total, 0, 1)));                      /* time since the pen passed */
      var off = AMP * env * (age > 0 ? Math.exp(-age / TAU) : 1) * Math.sin(s * 0.09 + t * 17);
      return (g.x + g.ux * u - g.uy * off).toFixed(1) + ' ' + (g.y + g.uy * u + g.ux * off).toFixed(1);
    }
    function straight() { ln.setAttribute('d', 'M' + pts.map(function (p) { return p.x.toFixed(1) + ' ' + p.y.toFixed(1); }).join(' L')); }
    function finish() { phase = 'done'; straight(); nodes.forEach(function (li) { li.classList.add('on'); }); fig.classList.add('is-done'); }
    function frame(now) {
      if (phase !== 'run') return;
      var t = (now - t0) / 1000, k = clamp(t / DUR, 0, 1), pen = (1 - Math.pow(1 - k, 3)) * total, d = '', s;
      for (s = 0; s < pen; s += 6) d += (d ? ' L' : 'M') + point(s, t);
      d += (d ? ' L' : 'M') + point(pen, t);
      ln.setAttribute('d', d);
      nodes.forEach(function (li, i) { var at = i === 0 ? 0 : segs[i - 1].s0 + segs[i - 1].l; if (pen >= at - 0.5) li.classList.add('on'); });
      if (t < DUR + TAU * 7) requestAnimationFrame(frame); else finish();
    }
    geom();
    if (phase === 'done') finish();
    else onceVisible(fig, function () { geom(); phase = 'run'; t0 = performance.now(); requestAnimationFrame(frame); }, { threshold: 0.4 });
    if (HAS_RO) new ResizeObserver(function () { geom(); if (phase === 'done') straight(); }).observe(fig);
  }

  /* ---------- checklists tick as they arrive ---------- */
  function ticks() {
    if (REDUCED || !HAS_IO) return;
    $all('.fc-ask .fc-ticks').forEach(function (list) {
      if (!belowFold(list)) return;
      list.classList.add('fc-tick-wait');
      onceVisible(list, function () { list.classList.remove('fc-tick-wait'); }, { threshold: 0.3 });
    });
  }

  /* ---------- 4 · Get listed: the line follows the reader, each step lights as it is reached ---------- */
  function sequence() {
    var seq = $('[data-fc-seq]'); if (!seq) return;
    var steps = kids(seq).filter(function (el) { return el.classList.contains('fc-step'); }), need = $('.fc-need', seq), ys = [];
    if (!steps.length) return;
    function geom() {
      var sr = seq.getBoundingClientRect();
      ys = steps.map(function (s) { return s.getBoundingClientRect().top - sr.top + (s.classList.contains('fc-step-go') ? 23 : 14); });
      seq.style.setProperty('--fc-y0', ys[0].toFixed(1) + 'px'); seq.style.setProperty('--fc-y1', ys[ys.length - 1].toFixed(1) + 'px');
    }
    geom();
    if (REDUCED) { seq.style.setProperty('--fc-p', '1'); steps.forEach(function (s) { s.classList.add('on'); }); return; }
    seq.classList.add('fc-seq-js');
    if (need && belowFold(need)) need.classList.add('fc-tick-wait');
    var tick = false, reach = -1e4;                  /* one way: once read, a step stays lit */
    function upd() {
      tick = false;
      var r = seq.getBoundingClientRect(), y0 = ys[0], y1 = ys[ys.length - 1];
      reach = Math.max(reach, window.innerHeight * 0.62 - r.top);
      seq.style.setProperty('--fc-p', clamp((reach - y0) / Math.max(1, y1 - y0), 0, 1).toFixed(4));
      steps.forEach(function (s, i) { if (reach >= ys[i] - 1) s.classList.add('on'); });
      if (need && steps[1] && steps[1].classList.contains('on')) need.classList.remove('fc-tick-wait');
    }
    window.addEventListener('scroll', function () { if (!tick) { tick = true; requestAnimationFrame(upd); } }, { passive: true });
    window.addEventListener('resize', function () { geom(); upd(); });
    if (HAS_RO) new ResizeObserver(function () { geom(); upd(); }).observe(seq);
    upd();
  }

  /* ---------- 5 · Close: the real faces behind both paths ---------- */
  function closeFaces() {
    if (!people().length) return;
    var list = ordered();
    $all('[data-fc-faces]').forEach(function (box) {
      var trainers = box.getAttribute('data-fc-faces') === 'trainer';
      box.innerHTML = faces(trainers ? list.filter(function (f) { return f.kind === 'trainer'; }) : list, 'fc-face');
    });
  }

  function init() {
    REDUCED = !!(window.TRELayer && window.TRELayer.reduced) || !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    [directory, strip, certPath, ticks, sequence, closeFaces].forEach(function (fn) {
      try { fn(); } catch (e) { setTimeout(function () { throw e; }, 0); }
    });
  }
  document.addEventListener('DOMContentLoaded', function () { setTimeout(init, 0); });
})();
